export function connectionsEvidence(record){if(!['statistics_lab','defects_lab','reciprocity_lab'].includes(record.action))return null;const e=record.result.learningEvidence||{},pair=e.comparison;return record.result.summary.map(s=>`${s.label}=${s.value}`).join('；')+`；符号步骤${e.symbolic?.result?.correct?'已验证':'未验证'}；A/B 完整证据${pair?'已保存':'未保存'}`+(pair?`\n\nA 参数：${JSON.stringify(pair.A.input)}\n\nB 参数：${JSON.stringify(pair.B.input)}\n\n对照解释：${pair.explanation||'尚未填写'}`:'');}
